// Payload may arrive as the WhatsApp Trigger output, the raw Meta envelope,
// or wrapped under .body. Try every plausible shape rather than assuming one.
const first = $input.first()?.json ?? {};
const candidates = [first, first.body, first.body?.entry?.[0]?.changes?.[0]?.value, first.entry?.[0]?.changes?.[0]?.value].filter(Boolean);

let value = null;
for (const c of candidates) {
  if (Array.isArray(c?.messages) && c.messages.length > 0) { value = c; break; }
}

// Delivery-status callbacks (sent / delivered / read) carry a `statuses` array
// and no `messages`. Normal traffic, not errors. Report and stop.
if (!value) {
  const isStatus = candidates.some(function (c) { return Array.isArray(c?.statuses); });
  return [{ json: { parsed: false, reason: isStatus ? 'delivery status callback' : 'no messages array found', sender_e164: '', button_norm: '', text_norm: '', context_wamid: '', top_level_keys: Object.keys(first).toString() } }];
}

const msg = value.messages[0];
const waId = msg.from ?? value.contacts?.[0]?.wa_id ?? '';

// Numbers are stored with a leading +; Meta returns them without one.
const senderE164 = waId ? (String(waId).charAt(0) === '+' ? String(waId) : '+' + String(waId)) : '';

// Quick-reply text arrives in two different shapes.
const rawButton = msg.button?.text ?? msg.interactive?.button_reply?.title ?? '';

// Never compare raw strings (Templates.md 3.2). Apostrophe strip runs FIRST.
const buttonNorm = String(rawButton).toLowerCase().replace(/[\u0027\u2018\u2019\u0060]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();

// Same normaliser for free text, so the SOS trigger matches on identical rules.
const textNorm = String(msg.text?.body ?? '').toLowerCase().replace(/[\u0027\u2018\u2019\u0060]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();

const ok = senderE164.length > 1;

return [{ json: { parsed: ok, reason: ok ? 'message' : 'message with no sender', sender_e164: senderE164, wa_id_raw: String(waId), message_type: msg.type ?? 'unknown', wa_message_id: msg.id ?? '', context_wamid: msg.context?.id ?? '', button_text_raw: String(rawButton), button_norm: buttonNorm, text_body: msg.text?.body ?? '', text_norm: textNorm } }];

const db = $input.first().json;
const parsed = $('Parse Inbound Message').first().json;

// Exact normalised forms of the approved button labels (Templates.md 3.2).
const CONSENT_YES = 'yes thats fine';
const CONSENT_NO = 'no thank you';
const MED_BUTTONS = ['yes all', 'some of them', 'not yet'];

// Whole-message exact match only (Talal, 3 Aug 2026). A contains-match would
// fire a three-person emergency on "can you help me with my tablets?".
const SOS_TRIGGERS = ['sos', 'help'];

// All four approved SOS resolution labels, normalised (Templates.md 3.2).
const SOS_RESOLVERS = ['i am responding', 'im responding', 'im on my way', 'acknowledge'];

let route = 'unhandled';

// SOS trigger is checked FIRST and short-circuits everything else (P2).
// Fires regardless of consent state, including a declined elder: she is the
// sender, and the alerts go to her care circle, not to her (S-4).
if (db.found === true && SOS_TRIGGERS.indexOf(parsed.text_norm) !== -1) {
  route = 'sos_trigger';
}

// SOS resolution comes from the care circle, who are NOT in elders, so this
// sits outside the db.found block. Attribution is by context_wamid in WF-4b,
// never by sender number - one person may hold several roles (S-6).
if (route === 'unhandled' && SOS_RESOLVERS.indexOf(parsed.button_norm) !== -1 && parsed.context_wamid) {
  route = 'sos_resolution';
}

if (route === 'unhandled' && db.found === true) {
  // Consent is only in play before she has confirmed or declined.
  if (db.consent_confirmed === false && db.consent_declined === false) {
    if (parsed.button_norm === CONSENT_YES) { route = 'consent_yes'; }
    else if (parsed.button_norm === CONSENT_NO) { route = 'consent_no'; }
  }

  // Medication replies only count for a consented elder. A declined or
  // pending elder should never be in a check-in cycle at all.
  if (route === 'unhandled' && db.consent_confirmed === true && db.consent_declined === false) {
    if (MED_BUTTONS.indexOf(parsed.button_norm) !== -1) { route = 'med_response'; }
  }
}

return [{ json: Object.assign({}, db, parsed, { route: route }) }];
